import React from 'react';
import { Bar, Line, Pie } from 'react-chartjs-2';
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend,
} from 'chart.js';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  LineElement,
  PointElement,
  ArcElement,
  Title,
  Tooltip,
  Legend
);

const AnalyticsDashboard = ({ events }) => {
  // Mock data for demonstration
  const eventStats = {
    totalEvents: events.length,
    upcomingEvents: events.filter(e => new Date(e.startDate) > new Date()).length,
    completedEvents: events.filter(e => new Date(e.endDate) < new Date()).length,
    categories: {
      personal: events.filter(e => e.category === 'personal').length,
      college: events.filter(e => e.category === 'college').length,
      professional: events.filter(e => e.category === 'professional').length,
      other: events.filter(e => e.category === 'other').length,
    }
  };

  const barData = {
    labels: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'],
    datasets: [
      {
        label: 'Events Created',
        data: [12, 19, 3, 5, 2, 3],
        backgroundColor: 'rgba(54, 162, 235, 0.5)',
        borderColor: 'rgba(54, 162, 235, 1)',
        borderWidth: 1,
      },
    ],
  };

  const lineData = {
    labels: ['Week 1', 'Week 2', 'Week 3', 'Week 4'],
    datasets: [
      {
        label: 'Event Attendance',
        data: [65, 59, 80, 81],
        fill: false,
        backgroundColor: 'rgba(75, 192, 192, 0.5)',
        borderColor: 'rgba(75, 192, 192, 1)',
      },
    ],
  };

  const pieData = {
    labels: ['Personal', 'College', 'Professional', 'Other'],
    datasets: [
      {
        data: [
          eventStats.categories.personal,
          eventStats.categories.college,
          eventStats.categories.professional,
          eventStats.categories.other,
        ],
        backgroundColor: [
          'rgba(255, 99, 132, 0.5)',
          'rgba(54, 162, 235, 0.5)',
          'rgba(255, 205, 86, 0.5)',
          'rgba(75, 192, 192, 0.5)',
        ],
        borderColor: [
          'rgba(255, 99, 132, 1)',
          'rgba(54, 162, 235, 1)',
          'rgba(255, 205, 86, 1)',
          'rgba(75, 192, 192, 1)',
        ],
        borderWidth: 1,
      },
    ],
  };

  const chartOptions = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
      },
    },
  };

  return (
    <div className="card">
      <h2 className="text-2xl font-bold mb-6">Event Analytics Dashboard</h2>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-8">
        <div className="bg-blue-50 p-4 rounded-lg">
          <h3 className="text-lg font-semibold text-blue-800">Total Events</h3>
          <p className="text-2xl font-bold text-blue-600">{eventStats.totalEvents}</p>
        </div>
        <div className="bg-green-50 p-4 rounded-lg">
          <h3 className="text-lg font-semibold text-green-800">Upcoming</h3>
          <p className="text-2xl font-bold text-green-600">{eventStats.upcomingEvents}</p>
        </div>
        <div className="bg-purple-50 p-4 rounded-lg">
          <h3 className="text-lg font-semibold text-purple-800">Completed</h3>
          <p className="text-2xl font-bold text-purple-600">{eventStats.completedEvents}</p>
        </div>
        <div className="bg-orange-50 p-4 rounded-lg">
          <h3 className="text-lg font-semibold text-orange-800">Success Rate</h3>
          <p className="text-2xl font-bold text-orange-600">95%</p>
        </div>
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div>
          <h3 className="text-lg font-semibold mb-4">Events by Month</h3>
          <Bar data={barData} options={chartOptions} />
        </div>

        <div>
          <h3 className="text-lg font-semibold mb-4">Event Categories</h3>
          <Pie data={pieData} options={chartOptions} />
        </div>

        <div className="lg:col-span-2">
          <h3 className="text-lg font-semibold mb-4">Attendance Trends</h3>
          <Line data={lineData} options={chartOptions} />
        </div>
      </div>

      {/* Recent Activity */}
      <div className="mt-8">
        <h3 className="text-lg font-semibold mb-4">Recent Activity</h3>
        <div className="space-y-2">
          <div className="flex justify-between items-center p-3 bg-gray-50 rounded">
            <span>Tech Conference 2024 created</span>
            <span className="text-sm text-gray-500">2 hours ago</span>
          </div>
          <div className="flex justify-between items-center p-3 bg-gray-50 rounded">
            <span>Birthday Party event completed</span>
            <span className="text-sm text-gray-500">1 day ago</span>
          </div>
          <div className="flex justify-between items-center p-3 bg-gray-50 rounded">
            <span>Workshop attendance: 45 participants</span>
            <span className="text-sm text-gray-500">3 days ago</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AnalyticsDashboard;
