import React, { useState, useEffect } from 'react';
import { Calendar, momentLocalizer } from 'react-big-calendar';
import moment from 'moment';
import 'react-big-calendar/lib/css/react-big-calendar.css';

const localizer = momentLocalizer(moment);

const CalendarView = ({ events, onEventUpdate }) => {
  const [calendarEvents, setCalendarEvents] = useState([]);

  useEffect(() => {
    // Transform events to calendar format
    const transformedEvents = events.map(event => ({
      id: event._id,
      title: event.title,
      start: new Date(event.startDate),
      end: new Date(event.endDate),
      resource: event,
    }));
    setCalendarEvents(transformedEvents);
  }, [events]);

  const handleSelectEvent = (event) => {
    // Handle event click - could open event details modal
    console.log('Selected event:', event);
  };

  const handleSelectSlot = ({ start, end }) => {
    // Handle empty slot click - could open create event modal
    console.log('Selected slot:', { start, end });
  };

  const eventStyleGetter = (event) => {
    let backgroundColor = '#3174ad'; // default blue

    // Color code based on category
    switch (event.resource.category) {
      case 'personal':
        backgroundColor = '#10b981'; // green
        break;
      case 'college':
        backgroundColor = '#f59e0b'; // yellow
        break;
      case 'professional':
        backgroundColor = '#ef4444'; // red
        break;
      default:
        backgroundColor = '#6b7280'; // gray
    }

    return {
      style: {
        backgroundColor,
        borderRadius: '4px',
        opacity: 0.8,
        color: 'white',
        border: '0px',
        display: 'block'
      }
    };
  };

  return (
    <div className="card">
      <h2 className="text-2xl font-bold mb-6">Event Calendar</h2>
      <div style={{ height: '600px' }}>
        <Calendar
          localizer={localizer}
          events={calendarEvents}
          startAccessor="start"
          endAccessor="end"
          style={{ height: '100%' }}
          onSelectEvent={handleSelectEvent}
          onSelectSlot={handleSelectSlot}
          selectable
          eventPropGetter={eventStyleGetter}
          views={['month', 'week', 'day']}
          defaultView="month"
        />
      </div>

      <div className="mt-4 flex flex-wrap gap-4 text-sm">
        <div className="flex items-center">
          <div className="w-4 h-4 bg-green-500 rounded mr-2"></div>
          Personal
        </div>
        <div className="flex items-center">
          <div className="w-4 h-4 bg-yellow-500 rounded mr-2"></div>
          College
        </div>
        <div className="flex items-center">
          <div className="w-4 h-4 bg-red-500 rounded mr-2"></div>
          Professional
        </div>
        <div className="flex items-center">
          <div className="w-4 h-4 bg-gray-500 rounded mr-2"></div>
          Other
        </div>
      </div>
    </div>
  );
};

export default CalendarView;
