import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import EventForm from '../components/EventForm';
import WeatherWidget from '../components/WeatherWidget';
import CalendarView from '../components/CalendarView';
import AIPlanner from '../components/AIPlanner';
import AnalyticsDashboard from '../components/AnalyticsDashboard';

const Dashboard = () => {
  const { user, logout } = useAuth();
  const [activeTab, setActiveTab] = useState('overview');
  const [events, setEvents] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // Load user's events
    fetchEvents();
  }, []);

  const fetchEvents = async () => {
    try {
      const response = await fetch('/api/events?myEvents=true');
      const data = await response.json();
      setEvents(data.events);
    } catch (error) {
      console.error('Failed to fetch events:', error);
    } finally {
      setLoading(false);
    }
  };

  const tabs = [
    { id: 'overview', name: 'Overview', icon: '📊' },
    { id: 'calendar', name: 'Calendar', icon: '📅' },
    { id: 'create', name: 'Create Event', icon: '➕' },
    { id: 'ai', name: 'AI Planner', icon: '🤖' },
    { id: 'analytics', name: 'Analytics', icon: '📈' },
  ];

  const renderTabContent = () => {
    switch (activeTab) {
      case 'overview':
        return (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <div className="card">
              <h3 className="text-lg font-semibold mb-4">Welcome back, {user?.name}!</h3>
              <p className="text-gray-600 mb-4">
                You have {events.length} upcoming events.
              </p>
              <WeatherWidget />
            </div>

            <div className="card">
              <h3 className="text-lg font-semibold mb-4">Quick Actions</h3>
              <div className="space-y-2">
                <button
                  onClick={() => setActiveTab('create')}
                  className="btn-primary w-full"
                >
                  Create New Event
                </button>
                <button
                  onClick={() => setActiveTab('ai')}
                  className="btn-secondary w-full"
                >
                  Ask AI Assistant
                </button>
              </div>
            </div>

            <div className="card">
              <h3 className="text-lg font-semibold mb-4">Recent Events</h3>
              {loading ? (
                <div className="animate-pulse space-y-2">
                  <div className="h-4 bg-gray-200 rounded"></div>
                  <div className="h-4 bg-gray-200 rounded"></div>
                  <div className="h-4 bg-gray-200 rounded"></div>
                </div>
              ) : events.length > 0 ? (
                <div className="space-y-2">
                  {events.slice(0, 3).map((event) => (
                    <div key={event._id} className="flex justify-between items-center">
                      <span className="text-sm font-medium">{event.title}</span>
                      <span className="text-xs text-gray-500">
                        {new Date(event.startDate).toLocaleDateString()}
                      </span>
                    </div>
                  ))}
                </div>
              ) : (
                <p className="text-gray-500 text-sm">No events yet</p>
              )}
            </div>
          </div>
        );

      case 'calendar':
        return <CalendarView events={events} onEventUpdate={fetchEvents} />;

      case 'create':
        return <EventForm onEventCreated={fetchEvents} />;

      case 'ai':
        return <AIPlanner />;

      case 'analytics':
        return <AnalyticsDashboard events={events} />;

      default:
        return null;
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <header className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-16">
            <h1 className="text-2xl font-bold text-gray-900">
              Event Planner
            </h1>
            <div className="flex items-center space-x-4">
              <span className="text-sm text-gray-600">
                Welcome, {user?.name}
              </span>
              <button
                onClick={logout}
                className="btn-secondary"
              >
                Logout
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="bg-white shadow-sm">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex space-x-8">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`py-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === tab.id
                    ? 'border-primary-500 text-primary-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                <span className="mr-2">{tab.icon}</span>
                {tab.name}
              </button>
            ))}
          </div>
        </div>
      </nav>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto py-6 px-4 sm:px-6 lg:px-8">
        {renderTabContent()}
      </main>
    </div>
  );
};

export default Dashboard;
